 change_group_visibility(group, !group->current_group_visibility);
}
}
else
{
 if(shift_held)
{
 toggle_selection(e->portable_id);
}
 else if(ctrl_held)
{
 Auto_Array <Entity *> temp;
 temp.add(e);
 Bounding_Box box;
 Vector3 focus = get_center(&box, &temp);
 set_camera_to_view_box(box);
